    public function test_consume_modify(): void
    {
        // @Arrange
        $source = new UserMfaRecoveryCode(
            uid: 'one',
            user: new UserRef('one'),
            codeHash: 'one',
            usedAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            createdAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            version: 1,
        );
        $sourceUsedAt = (new \DateTimeImmutable('1980-08-20T14:32:45.123Z'));
        $targetUsedAt = (new \DateTimeImmutable('1981-09-06T14:32:45.123Z'));
        $source = $source->withUsedAt($sourceUsedAt);

        // @Act
        $target = $source->consume($targetUsedAt);

        // @Assert
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $source->getUsedAt());
        $this->assertEquals((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')), $target->getUsedAt());
        $this->assertNotEquals($sourceUsedAt, $target->getUsedAt());
    }
}
